    if (t == 1) r = sumRange(l, 1, 4);
    if (t == 2) r = sumRange(l, 0, 6);
    if (t == 3) r = sumRange(l, 3, 3);
    if (t == 4) r = sumRange(l, 5, 6);
    if (t == 5) r = kthLargest(s, 1);
