    //   after dequeue (gives 1):  [ ][2][3][ ]    head = 1, len = 2
    //   after enqueue 4, 5:       [5][2][3][4]    head = 1, len = 4   (5 wrapped to slot 0)
    let capacity = 4;
    let head = 1;
